#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;
    long long k;
    cin >> k;

    if (k == 1 || k >= (long long) s.size()) {
        cout << s << "\n";
    } else {
        vector<string> lines(k);
        int row = 0, step = 1;
        for (char ch : s) {
            lines[row] += ch;
            if (row == 0) step = 1;
            else if (row == k - 1) step = -1;
            row += step;
        }
        for (const string& line : lines) cout << line;
        cout << "\n";
    }

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        long k = sc.nextLong();

        if (k == 1 || k >= s.length()) {
            System.out.println(s);
        } else {
            StringBuilder[] lines = new StringBuilder[(int) k];
            for (int i = 0; i < k; i++) lines[i] = new StringBuilder();
            int row = 0, step = 1;
            for (int i = 0; i < s.length(); i++) {
                lines[row].append(s.charAt(i));
                if (row == 0) step = 1;
                else if (row == k - 1) step = -1;
                row += step;
            }
            StringBuilder out = new StringBuilder();
            for (StringBuilder line : lines) out.append(line);
            System.out.println(out);
        }
    }
}
